from pathlib import Path
import base64,zlib,runpy,subprocess,sys
sys.stdout.reconfigure(encoding='utf-8',errors='backslashreplace')
out=Path(__file__).parent;r=out.parents[1]
(out/'install.py').write_bytes(zlib.decompress(base64.b64decode('')))
runpy.run_path(str(out/'install.py'),run_name='__main__')
engine=str(r.parent/'Godot/Godot_v4.7.2-stable_win64_console.exe')
for label,args in [('bake',['--script','res://tools/dusk_review/bake_harold_frontage.gd','--','--ground-only']),('import',['--headless','--editor','--import'])]:
 with (out/(label+'.log')).open('w',encoding='utf-8') as log:
  result=subprocess.run([engine,'--path',str(r),*args],stdout=log,stderr=subprocess.STDOUT,timeout=150)
 print(label,result.returncode,flush=True)
 print((out/(label+'.log')).read_text(encoding='utf-8')[-2500:],flush=True)
 if result.returncode!=0:sys.exit(result.returncode)